insert into public.services(id,slug,name,tagline,description,image,sort_order) values
('11111111-1111-4111-8111-111111111111','pranje-tepiha','Pranje tepiha','Svežina koju vaš dom zaslužuje.','Osvežite svoj omiljeni kutak. Pošaljite nam dimenzije i vrstu tepiha, a pre potvrde dogovorićemo način preuzimanja, pranje i povratak.','/images/carpet.jpg',1),
('22222222-2222-4222-8222-222222222222','iznosenje-smeca','Iznošenje smeća','Jedna obaveza manje. Svakog dana.','Diskretno preuzimanje kućnog smeća i reciklaže u dogovorenom terminu, zamena kese i uredan prostor oko kante. Navedite količinu, sprat i lift; redovne dolaske planiramo prema vašoj adresi.','/images/kitchen.jpg',2),
('33333333-3333-4333-8333-333333333333','ugradnja-tv-a','Montaža TV-a','Vaše malo kućno bioskopsko veče.','Provera zida i nosača, dogovor o visini, zaštita prostora, montaža i povezivanje televizora. Uređujemo kablove i prostor nakon rada; nosač i skrivanje kablova u zidu navodimo posebno u ponudi.','/images/living.jpg',3),
('44444444-4444-4444-8444-444444444444','zamena-sijalica','Zamena sijalica','Mala promena. Lepše svetlo.','Vratite toplinu u svaki kutak doma. Navedite broj sijalica, vrstu rasvete i visinu plafona. Nabavku sijalica dogovaramo pre dolaska.','/images/lamp.jpg',4),
('55555555-5555-4555-8555-555555555555','servis-klime','Servis klime','Savršena temperatura za vaš mir.','Za prijatnije dane kod kuće. Navedite model klime, pristupačnost uređaja i da li vam je potrebno redovno održavanje ili pregled kvara.','/images/air.jpg',5),
('ca5a0000-0000-4000-8000-000000000006','kacenje-slika-i-ogledala','Kačenje slika i ogledala','Sve na svom mestu.','Dogovaramo raspored i visinu, proveravamo zid i pričvršćenja, postavljamo slike ili ogledala i ostavljamo prostor urednim.','/images/living.jpg',6),
('ca5a0000-0000-4000-8000-000000000007','montaza-polica','Montaža polica i nosača','Sve na svom mestu.','Postavljamo police, zidne nosače i kupatilske dodatke uz proveru podloge, nosivosti i položaja. Materijal i obim dogovaramo pre dolaska.','/images/living.jpg',7),
('ca5a0000-0000-4000-8000-000000000008','postavljanje-garnisni','Postavljanje garnišni i zavesa','Sve na svom mestu.','Montiramo garnišne, postavljamo zavese i podešavamo dostupne mehanizme roletni. Mere, podlogu i potrebne delove dogovaramo unapred.','/images/living.jpg',8),
('ca5a0000-0000-4000-8000-000000000009','sklapanje-namestaja','Sklapanje nameštaja','Sve na svom mestu.','Sklapamo komode, stolove, stolice i drugi nameštaj prema uputstvu, podešavamo elemente i sređujemo ambalažu nakon rada.','/images/living.jpg',9),
('ca5a0000-0000-4000-8000-000000000010','podesavanje-vrata-i-fioka','Podešavanje vrata i fioka','Detalji pod kontrolom.','Podešavamo šarke i klizače, zatežemo spojeve i menjamo dogovorene ručke ili okove, za nameštaj koji ponovo radi sa lakoćom.','/images/kitchen.jpg',10),
('ca5a0000-0000-4000-8000-000000000011','obnova-silikona','Obnova silikona','Detalji pod kontrolom.','Uklanjamo dotrajali silikon i obnavljamo dogovorene spojeve oko kade, tuša ili sudopere. Obim i vreme sušenja potvrđujemo pre rada.','/images/kitchen.jpg',11),
('ca5a0000-0000-4000-8000-000000000012','sitne-popravke-zidova','Sitne popravke zidova','Detalji pod kontrolom.','Popunjavamo manje rupe i oštećenja i radimo lokalne popravke boje. Nijansu, materijal i površinu usaglašavamo pre dolaska.','/images/living.jpg',12),
('ca5a0000-0000-4000-8000-000000000013','vodoinstalaterske-intervencije','Vodoinstalaterske intervencije','Detalji pod kontrolom.','Naš stručni tim pregleda slavine, sifone i vodokotliće i izvodi dogovorene manje popravke ili zamene. Delove navodimo posebno u ponudi.','/images/kitchen.jpg',13),
('ca5a0000-0000-4000-8000-000000000014','elektricarske-intervencije','Električarske intervencije','Detalji pod kontrolom.','Naš stručni tim obavlja dogovorene popravke i zamene rasvete, prekidača i utičnica nakon provere instalacije i obima posla.','/images/lamp.jpg',14),
('ca5a0000-0000-4000-8000-000000000015','odrzavanje-filtera','Održavanje dostupnih filtera','Detalji pod kontrolom.','Čistimo ili menjamo dostupne filtere aspiratora i kućnih uređaja prema uputstvu proizvođača. Model i potrošni materijal proveravamo unapred.','/images/air.jpg',15),
('ca5a0000-0000-4000-8000-000000000016','podesavanje-tv-a','Podešavanje TV-a i zvuka','Povezano sa lakoćom.','Povezujemo televizor, soundbar i postojeće uređaje, podešavamo dostupne aplikacije i pokazujemo vam osnovne funkcije.','/images/living.jpg',16),
('ca5a0000-0000-4000-8000-000000000017','podesavanje-wifi-mreze','Podešavanje Wi-Fi mreže','Povezano sa lakoćom.','Podešavamo ruter i pojačivače signala, povezujemo uređaje i proveravamo vezu u dogovorenim prostorijama.','/images/living.jpg',17),
('ca5a0000-0000-4000-8000-000000000018','pametni-uredjaji','Povezivanje pametnih uređaja','Povezano sa lakoćom.','Podešavamo kompatibilne pametne sijalice, utičnice i druge kućne uređaje, kao i štampače, uz vaše prisustvo pri prijavljivanju na naloge.','/images/lamp.jpg',18),
('ca5a0000-0000-4000-8000-000000000019','nega-garderobe','Nega garderobe','Više vremena za vas.','Peglamo i slažemo odeću prema uputstvima za negu, pripremamo veš za pranje i odlažemo stvari prema vašim navikama.','/images/club.jpg',19),
('ca5a0000-0000-4000-8000-000000000020','sveza-posteljina','Sveža posteljina','Više vremena za vas.','Menjamo vašu pripremljenu posteljinu, pažljivo nameštamo krevet i pripremamo korišćenu posteljinu za pranje.','/images/hero.jpg',20),
('ca5a0000-0000-4000-8000-000000000021','organizacija-doma','Organizacija doma','Više vremena za vas.','Sređujemo garderober, ostavu i kuhinjske elemente sa vama, organizujemo sezonske stvari i pripremamo dogovorene predmete za donaciju.','/images/kitchen.jpg',21),
('ca5a0000-0000-4000-8000-000000000022','licna-nabavka','Vaša lična nabavka','Više vremena za vas.','Kupujemo prema vašoj listi, dogovaramo zamene proizvoda i raspoređujemo namirnice po dolasku. Proizvode i uslugu iskazujemo odvojeno.','/images/kitchen.jpg',22),
('ca5a0000-0000-4000-8000-000000000023','paketi-i-hemijsko-ciscenje','Paketi i hemijsko čišćenje','Više vremena za vas.','Preuzimamo dogovorene pakete i odnosimo ili vraćamo garderobu sa hemijskog čišćenja. Troškove trećih strana potvrđujete unapred.','/images/club.jpg',23),
('ca5a0000-0000-4000-8000-000000000024','dom-na-cuvanju','Dom na čuvanju','Više vremena za vas.','Tokom vašeg odsustva zalivamo biljke, obilazimo stan i šaljemo kratak izveštaj. Pristup i listu zadataka dogovaramo pre putovanja.','/images/hero.jpg',24),
('ca5a0000-0000-4000-8000-000000000025','pakovanje-i-raspakivanje','Pakovanje i raspakivanje','Više vremena za vas.','Pomažemo da pažljivo spakujete stvari ili uredite novi dom nakon selidbe. Ambalažu, obim i eventualno pomeranje težih predmeta dogovaramo posebno.','/images/living.jpg',25),
('ca5a0000-0000-4000-8000-000000000026','dom-spreman-za-goste','Dom spreman za goste','Više vremena za vas.','Uređujemo dogovoreni prostor, pripremamo posteljinu i postavljamo sto sa vašim posuđem i dekoracijom, uz pažnju prema završnim detaljima.','/images/kitchen.jpg',26),
('ca5a0000-0000-4000-8000-000000000100','moja-casa','Moja Casa','Briga o domu, po vašoj meri.','Sastavite svoj izbor usluga i učestalost dolazaka. Naš tim potvrđuje obim, dostupnost i konačnu ponudu pre početka saradnje.','/images/hero.jpg',100)
